///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkSave
 * @description check Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSave = async function () {
    const uploadCodeFile = (String(((dma_pageContext.get("uploadCodeFile") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCodeFile") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("uploadCodeFile") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCodeFile") ?? ""))));
    if (uploadCodeFile === '0') {
        await $c.win.alert('저장되었습니다.');
    } else {
        if (uploadCodeFile === '1') {
            await $c.win.alert('해당유형의 파일은 업로드할 수 없습니다.');
        } else {
            if (uploadCodeFile === '2') {
                await $c.win.alert('업로드 하려는 파일의 크기가 허용한도를 초과 하였습니다.');
            } else {
                await $c.win.alert('저장시 오류가 발생하였습니다.');
            }
        }
    }
};

/**
 * @method
