 */
scwin.searchDiscls = function () {
    const p = {}; p["method"] = $c.util.getComponent("dma_SearchReq").get("method"); p["pageIndex"] = $c.util.getComponent("dma_SearchReq").get("pageIndex"); $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil21212/jldfil21212.xml', p);
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
